// ============================================================
// PULSECHAIN MASTER NORMALIZER
// Accepts any raw API response and produces canonical events.
// ============================================================

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(16);
}

const regionNames = {
  northeast: 'Northeastern US',
  southeast: 'Southeastern US',
  midwest:   'Midwestern US',
  west:      'Western US'
};

const allItems = $input.all();
const results = [];

function processRow(row) {
  // ---- WASTEWATER (CDC NWSS rows) ----
  if (row.pcr_conc_smoothed !== undefined || row.wwtp_jurisdiction !== undefined) {
    if (!row.pcr_conc_smoothed || !row.wwtp_jurisdiction || !row.date_end) return;
    const signal = parseFloat(row.pcr_conc_smoothed);
    if (isNaN(signal)) return;
    const id = simpleHash('wastewater:' + row.wwtp_jurisdiction + ':' + row.date_end);
    results.push({ json: {
      event_id: id,
      source: 'wastewater',
      signal_key: 'pulsechain.wastewater',
      region: row.wwtp_jurisdiction,
      region_name: row.wwtp_jurisdiction,
      signal_value: signal,
      unit: 'copies_per_ml',
      source_ts: row.date_end,
      raw_payload: JSON.stringify(row),
      ingested_at: new Date().toISOString()
    }});
    return;
  }

  // ---- PHARMACY ----
  if (row.source === 'pharmacy' || row.purchase_index !== undefined) {
    const signal = parseFloat(row.purchase_index) || 0;
    const id = simpleHash('pharmacy:' + (row.region||'unknown') + ':' + (row.timestamp || row.source_ts || Date.now()));
    results.push({ json: {
      event_id: id,
      source: 'pharmacy',
      signal_key: 'pulsechain.pharmacy',
      region: row.region || 'unknown',
      region_name: row.region_name || regionNames[row.region] || row.region || 'unknown',
      signal_value: signal,
      unit: 'purchase_index',
      source_ts: row.timestamp || row.source_ts || new Date().toISOString(),
      ingested_at: new Date().toISOString()
    }});
    return;
  }

  // ---- SEARCH TRENDS ----
  if (row.source === 'search_trends' || row.search_index !== undefined) {
    const signal = parseFloat(row.search_index ?? row.purchase_index) || 0;
    const id = simpleHash('search_trends:' + (row.region||'unknown') + ':' + (row.timestamp || row.source_ts || Date.now()));
    results.push({ json: {
      event_id: id,
      source: 'search_trends',
      signal_key: 'pulsechain.search_trends',
      region: row.region || 'unknown',
      region_name: row.region_name || regionNames[row.region] || row.region || 'unknown',
      signal_value: signal,
      unit: 'search_index',
      source_ts: row.timestamp || row.source_ts || new Date().toISOString(),
      ingested_at: new Date().toISOString()
    }});
    return;
  }

  // ---- ABSENTEEISM ----
  if (row.source === 'absenteeism' || row.absenteeism_rate !== undefined) {
    const signal = parseFloat(row.absenteeism_rate ?? row.rate ?? row.index) || 0;
    const id = simpleHash('absenteeism:' + (row.region||'unknown') + ':' + (row.timestamp || row.source_ts || Date.now()));
    results.push({ json: {
      event_id: id,
      source: 'absenteeism',
      signal_key: 'pulsechain.absenteeism',
      region: row.region || 'unknown',
      region_name: row.region_name || regionNames[row.region] || row.region || 'unknown',
      signal_value: signal,
      unit: 'absenteeism_rate',
      source_ts: row.timestamp || row.source_ts || new Date().toISOString(),
      ingested_at: new Date().toISOString()
    }});
    return;
  }

  // ---- ED TRIAGE ----
  if (row.source === 'ed_triage' || row.triage_index !== undefined || row.visit_index !== undefined) {
    const signal = parseFloat(row.triage_index ?? row.visit_index ?? row.severity_score ?? row.index) || 0;
    const id = simpleHash('ed_triage:' + (row.region||'unknown') + ':' + (row.timestamp || row.source_ts || Date.now()));
    results.push({ json: {
      event_id: id,
      source: 'ed_triage',
      signal_key: 'pulsechain.ed_triage',
      region: row.region || 'unknown',
      region_name: row.region_name || regionNames[row.region] || row.region || 'unknown',
      signal_value: signal,
      unit: 'triage_index',
      source_ts: row.timestamp || row.source_ts || new Date().toISOString(),
      ingested_at: new Date().toISOString()
    }});
    return;
  }
}

for (const item of allItems) {
  const row = item.json;
  if (!row) continue;

  // Handle wrapped API responses with a data array
  if (Array.isArray(row.data)) {
    for (const sub of row.data) {
      processRow(sub);
    }
  } else if (Array.isArray(row)) {
    for (const sub of row) {
      processRow(sub);
    }
  } else {
    processRow(row);
  }
}

console.log('Normalized ' + results.length + ' events from ' + allItems.length + ' raw items');
return results.length > 0 ? results : [{ json: { _empty: true } }];

// ============================================================
// VALIDATION GATE
// Output 0 = valid events → Kafka publish
// Output 1 = invalid events → DLQ
// ============================================================
const items = $input.all();
const valid = [];
const invalid = [];

for (const item of items) {
  const d = item.json;
  if (!d || d._empty) continue;

  const errors = [];
  if (!d.event_id) errors.push('missing event_id');
  if (d.signal_value === undefined || d.signal_value === null) errors.push('missing signal_value');
  if (typeof d.signal_value !== 'number') errors.push('signal_value not numeric');
  if (!d.region) errors.push('missing region');
  if (!d.source) errors.push('missing source');

  if (d.source === 'wastewater' && (d.signal_value < 0 || d.signal_value > 50000000)) {
    errors.push('wastewater value out of range: ' + d.signal_value);
  }
  if (['pharmacy','search_trends','absenteeism','ed_triage'].includes(d.source)) {
    if (d.signal_value < 0 || d.signal_value > 1000) {
      errors.push('index value out of range: ' + d.signal_value);
    }
  }

  if (errors.length === 0) {
    valid.push(item);
  } else {
    invalid.push({ json: { ...d, validation_errors: errors, dlq_reason: errors.join('; ') } });
  }
}

console.log('Validation: ' + valid.length + ' valid, ' + invalid.length + ' invalid');
return [valid, invalid];

// ============================================================
// EVENT ENRICHMENT + ID GUARANTEE
// ============================================================
const e = $input.first().json || {};

// crypto is available in n8n Code nodes via require
let id = e.event_id;
if (!id) {
  // Use a simple deterministic hash without require('crypto')
  const str = (e.source || 'unknown') + ':' + (e.region || 'unknown') + ':' + (e.source_ts || Date.now());
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  id = 'evt_' + Math.abs(hash).toString(16);
}

return [{ json: { ...e, event_id: id, enriched_at: new Date().toISOString() } }];

// ============================================================
// Z-SCORE ANOMALY DETECTOR
// ============================================================
// Get the enriched event from the Enrich node
let event;
try {
  event = $('🔑 Enrich + Guarantee ID').first().json;
} catch(e) {
  event = $input.first().json;
}

const baselineRows = $input.all();
const baseline = (baselineRows.length > 0 && !baselineRows[0].json.error) ? baselineRows[0].json : null;

let z_score = 0;
let is_anomaly = false;
let detection_method = 'z_score';

if (baseline && baseline.std_dev && parseFloat(baseline.std_dev) > 0) {
  z_score = (event.signal_value - parseFloat(baseline.mean_value)) / parseFloat(baseline.std_dev);
  is_anomaly = Math.abs(z_score) >= 2.0;
} else {
  detection_method = 'heuristic';
  const thresholds = {
    wastewater:    100000,
    pharmacy:      70,
    search_trends: 65,
    absenteeism:   0.15,
    ed_triage:     60
  };
  const threshold = thresholds[event.source] || 50;
  is_anomaly = event.signal_value > threshold;
  z_score = is_anomaly ? 2.5 : 0;
}

z_score = Math.round(z_score * 100) / 100;

console.log('Anomaly check | ' + event.source + ' | ' + event.region +
  ' | value=' + event.signal_value +
  ' | z=' + z_score +
  ' | anomaly=' + is_anomaly +
  ' | method=' + detection_method);

return [{ json: {
  ...event,
  z_score,
  is_anomaly,
  detection_method,
  baseline_mean: baseline ? parseFloat(baseline.mean_value) : null,
  baseline_std:  baseline ? parseFloat(baseline.std_dev) : null,
  signal_context: {
    [event.source]: {
      value: event.signal_value,
      z_score,
      trust: 1.0,
      freshness: 1.0
    }
  },
  analyzed_at: new Date().toISOString()
}}];

// ============================================================
// MULTI-SIGNAL AGGREGATOR / FUSION PAYLOAD BUILDER
// ============================================================
const event = $input.first().json;

const signal_values = {
  [event.source]: event.signal_value
};

return [{ json: {
  region:          event.region,
  region_name:     event.region_name || event.region,
  signal_values:   signal_values,
  signals:         event.signal_context,
  prior:           0.02,
  observed_values: { [event.source]: event.signal_value },
  explain:         true,
  forecast_spread: true,
  horizon_days:    14,
  pathogen:        'influenza',
  event_id:        event.event_id,
  z_score:         event.z_score,
  source:          event.source,
  signal_value:    event.signal_value,
  _upstream:       event
}}];

// ============================================================
// BAYESIAN RESULT MERGER
// Merges whichever fusion API responded; graceful fallback.
// ============================================================
let upstream = {};
try { upstream = $('🧩 Build Fusion Payload').first().json._upstream || {}; } catch(e) {}

let enhanced = null;
try {
  const r = $('🧠 Call Enhanced Analysis API').first();
  if (r && r.json && !r.json.error) enhanced = r.json;
} catch(e) {}

let simple = null;
try {
  const r = $('🔬 Call Simple Fusion Engine').first();
  if (r && r.json && !r.json.error) simple = r.json;
} catch(e) {}

const fusion = enhanced || simple || {};
const bf = fusion.bayesian_fusion || fusion || {};

const posterior = bf.posterior_probability ??
                  fusion.posterior_probability ??
                  (upstream.z_score ? Math.min(0.99, Math.abs(upstream.z_score) / 4) : 0);

const rawTier = bf.alert_tier ?? fusion.alert_tier;
let alert_tier = rawTier;
if (alert_tier === undefined) {
  alert_tier = posterior >= 0.75 ? 1 : posterior >= 0.50 ? 2 : posterior >= 0.25 ? 3 : 0;
}

const tierLabels = { 0: 'NORMAL', 1: 'EMERGENCY', 2: 'ADVISORY', 3: 'WATCH' };

const merged = {
  event_id:              upstream.event_id || ('evt_' + Date.now()),
  region:                upstream.region,
  region_name:           upstream.region_name || upstream.region,
  source:                upstream.source,
  signal_value:          upstream.signal_value,
  z_score:               upstream.z_score,
  posterior_probability: parseFloat(posterior) || 0,
  credible_interval:     bf.credible_interval || null,
  confidence:            bf.confidence ?? (posterior > 0.5 ? 0.8 : 0.6),
  dominant_signal:       bf.dominant_signal || upstream.source,
  alert_tier:            parseInt(alert_tier) || 0,
  tier_label:            tierLabels[parseInt(alert_tier)] || 'UNKNOWN',
  drivers:               bf.drivers || fusion.drivers || [],
  recommended_actions:   bf.recommended_actions || fusion.recommended_actions || [],
  explanation_summary:   bf.explanation_summary || fusion.explanation_summary ||
                         (fusion.explanation && fusion.explanation.summary) ||
                         (upstream.source + ' anomaly detected in ' + (upstream.region_name || upstream.region) + ' (z=' + upstream.z_score + ')'),
  explanation_markdown:  (fusion.explanation && fusion.explanation.markdown) || '',
  spread_forecast:       bf.spread_forecast || fusion.spread_forecast || null,
  lead_time_estimate:    bf.lead_time_estimate || '3-7 days',
  log_odds_ratio:        (fusion.fusion && fusion.fusion.log_odds_ratio) || null,
  bayesian_method:       (fusion.fusion && fusion.fusion.method) || 'naive_bayes',
  fusion_source:         enhanced ? 'enhanced_api' : (simple ? 'simple_fusion' : 'heuristic'),
  pipeline_version:      '3.0',
  assessed_at:           new Date().toISOString(),
  workflow_execution_id: $execution.id || null
};

console.log('=== BAYESIAN FUSION COMPLETE ===');
console.log('Region:     ' + merged.region_name);
console.log('Tier:       ' + merged.alert_tier + ' (' + merged.tier_label + ')');
console.log('Posterior:  ' + (merged.posterior_probability * 100).toFixed(1) + '%');
console.log('Confidence: ' + (merged.confidence * 100).toFixed(0) + '%');
console.log('Fusion src: ' + merged.fusion_source);

return [{ json: merged }];

// ALERT TIER NORMALIZER
const d = $input.first().json;

let tier = parseInt(d.alert_tier);
if (isNaN(tier)) {
  if (d.severity === 'critical') tier = 1;
  else if (d.severity === 'warning') tier = 2;
  else if (d.severity === 'watch') tier = 3;
  else {
    const score = parseFloat(d.posterior_probability || d.risk_score) || 0;
    tier = score >= 0.75 ? 1 : score >= 0.50 ? 2 : score >= 0.25 ? 3 : 0;
  }
}

const tierLabels = { 1: 'EMERGENCY', 2: 'ADVISORY', 3: 'WATCH', 0: 'NORMAL' };
console.log('Routing tier ' + tier + ' (' + tierLabels[tier] + ') for ' + (d.region_name || d.region));

return [{ json: { ...d, alert_tier: tier, tier_label: tierLabels[tier] || 'UNKNOWN', routed_at: new Date().toISOString() } }];

const d = $input.first().json;
console.log('🚨 TIER 1 EMERGENCY ALERT');
console.log('Region:', d.region_name);
console.log('Score:', ((d.posterior_probability || 0) * 100).toFixed(1) + '%');

const message = [
  '🚨 PULSECHAIN — TIER 1 EMERGENCY',
  '================================',
  'Region:       ' + (d.region_name || d.region),
  'Risk Score:   ' + ((d.posterior_probability || 0) * 100).toFixed(1) + '%',
  'Confidence:   ' + ((d.confidence || 0) * 100).toFixed(0) + '%',
  'Dominant:     ' + (d.dominant_signal || d.source),
  '',
  'Summary: ' + (d.explanation_summary || 'Anomaly detected'),
  '',
  'Recommended Actions:',
  ...(d.recommended_actions || ['Activate emergency response protocol', 'Notify regional health authority']).map(a => '  • ' + a),
  '',
  'Assessment ID: ' + d.event_id,
  'Timestamp: ' + d.assessed_at
].join('\n');

return [{ json: { ...d, notification_channel: 'tier1_emergency', notification_message: message, notification_sent_at: new Date().toISOString(), actually_notified: false } }];

const d = $input.first().json;
console.log('⚠️ TIER 2 ADVISORY ALERT');
console.log('Region:', d.region_name);
console.log('Score:', ((d.posterior_probability || 0) * 100).toFixed(1) + '%');

const message = [
  '⚠️ PULSECHAIN — TIER 2 ADVISORY',
  'Region:       ' + (d.region_name || d.region),
  'Risk Score:   ' + ((d.posterior_probability || 0) * 100).toFixed(1) + '%',
  'Summary: ' + (d.explanation_summary || 'Advisory signal detected'),
  'Assessment ID: ' + d.event_id
].join('\n');

return [{ json: { ...d, notification_channel: 'tier2_advisory', notification_message: message, notification_sent_at: new Date().toISOString(), actually_notified: false } }];

const d = $input.first().json;
console.log('👁 TIER 3 WATCH MODE — ' + (d.region_name || d.region));
return [{ json: { ...d, notification_channel: 'tier3_watch', notification_message: '👁 WATCH: ' + (d.region_name || d.region) + ' | Score: ' + ((d.posterior_probability || 0) * 100).toFixed(1) + '%', notification_sent_at: new Date().toISOString(), actually_notified: false } }];

const d = $input.first().json;
console.log('✅ Normal — no alert for ' + (d.region_name || d.region));
return [{ json: { ...d, notification_channel: 'none', notification_sent_at: new Date().toISOString(), actually_notified: false } }];

// ============================================================
// RECORD DISPATCH + AUDIT
// ============================================================
const d = $input.first().json;
const dispatch_id = 'disp_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
const log_id      = 'log_'  + Date.now() + '_' + Math.random().toString(36).slice(2, 8);

return [{ json: {
  ...d,
  dispatch: {
    dispatch_id,
    assessment_id:   d.event_id || dispatch_id,
    alert_tier:      d.alert_tier || 0,
    region:          d.region || 'unknown',
    channel:         d.notification_channel || 'none',
    status:          'sent',
    message_preview: (d.notification_message || '').substring(0, 200),
    sent_at:         d.notification_sent_at || new Date().toISOString()
  },
  audit: {
    log_id,
    workflow_id:    'pulsechain_unified_v3',
    execution_id:   $execution.id || 'unknown',
    node_name:      'record_dispatch',
    action:         'alert_dispatched',
    decision_tier:  d.alert_tier || 0,
    operator_id:    'system',
    metadata:       JSON.stringify({ tier: d.alert_tier, region: d.region, source: d.source, z_score: d.z_score }),
    logged_at:      new Date().toISOString()
  }
}}];

const items = $input.all();
const count = items.filter(i => i.json && !i.json._empty && !i.json.error).length;
console.log('SLA check: ' + count + ' dispatches pending acknowledgment');
return [{ json: { count, checked_at: new Date().toISOString() } }];

// ERROR CLASSIFIER
const e = $input.first().json || {};
const msg = (e.error && e.error.message) || 'Unknown error';
let severity = 'warning';
let page = false;
let retry = true;

const errorName = (e.error && e.error.name) || '';
if (['NodeConnectionError','NetworkError'].includes(errorName)) {
  severity = 'error';
} else if (errorName === 'AuthenticationError') {
  severity = 'critical';
  page = true;
  retry = false;
} else if (msg.toLowerCase().includes('kafka') || msg.toLowerCase().includes('postgres')) {
  severity = 'critical';
  page = true;
}

console.error('PulseChain Error | ' + severity + ' | ' + msg);

return [{ json: {
  error_id:       'err_' + Date.now() + '_' + Math.random().toString(36).slice(2,8),
  workflow_name:  (e.workflow && e.workflow.name) || 'pulsechain_unified_v3',
  execution_id:   (e.execution && e.execution.id) || $execution.id,
  error_type:     errorName || 'Error',
  error_message:  msg,
  severity,
  should_page:    page,
  should_retry:   retry,
  occurred_at:    new Date().toISOString(),
  raw_error:      JSON.stringify(e).substring(0, 1000)
}}];
